def _tables():
    knowledge = sa.table("scenario_knowledge",
        sa.column("id", sa.String(36)), sa.column("scenario_id", sa.String(50)),
        sa.column("keywords", pg.ARRAY(sa.Text())), sa.column("context", sa.Text()),
        sa.column("priority", sa.Integer()), sa.column("enabled", sa.Boolean()),
        sa.column("version", sa.Integer()))
    questions = sa.table("interview_questions",
        sa.column("id", sa.String(36)), sa.column("scenario_id", sa.String(50)),
        sa.column("text", sa.Text()), sa.column("topic", sa.String(100)),
        sa.column("difficulty", sa.String(30)), sa.column("reference_answer", sa.Text()),
        sa.column("required_points", pg.JSONB()), sa.column("common_errors", pg.JSONB()),
        sa.column("version", sa.Integer()), sa.column("enabled", sa.Boolean()))
    links = sa.table("interview_question_knowledge",
        sa.column("question_id", sa.String(36)), sa.column("knowledge_id", sa.String(36)))
    return knowledge, questions, links


def _ids():
    # Отдельное пространство ID: исходные 10000000/20000000 не затрагиваются.
    for topic_number, (topic, keywords, entries) in enumerate(POOL, 1):
        for position, entry in enumerate(entries, 1):
            number = topic_number * 100 + position
            yield (f"15000000-0000-4000-8000-{number:012d}",
                   f"25000000-0000-4000-8000-{number:012d}", topic, keywords, entry)


def upgrade():
    knowledge, questions, links = _tables()
    for kid, qid, topic, keywords, (question, reference, points, error) in _ids():
        op.bulk_insert(knowledge, [dict(id=kid, scenario_id="interview", keywords=keywords,
            context=reference, priority=10, enabled=True, version=1)])
        op.bulk_insert(questions, [dict(id=qid, scenario_id="interview", text=question,
            topic=topic, difficulty="basic", reference_answer=reference,
            required_points=points, common_errors=[error], version=1, enabled=True)])
        op.bulk_insert(links, [dict(question_id=qid, knowledge_id=kid)])


def downgrade():
    knowledge, questions, links = _tables()
    rows = list(_ids())
    question_ids = [row[1] for row in rows]
    knowledge_ids = [row[0] for row in rows]
    # FK interview_items не даст удалить использованные вопросы: вся транзакция
    # отката миграции отменится, история интервью останется нетронутой.
    op.execute(links.delete().where(links.c.question_id.in_(question_ids)))
    op.execute(questions.delete().where(questions.c.id.in_(question_ids)))
    op.execute(knowledge.delete().where(knowledge.c.id.in_(knowledge_ids)))
